using IdleIntelligence.Core;
using UnityEngine;
namespace IdleIntelligence.Runtime
{
    public sealed class UnitySaveCodec : IVersionedSaveCodec
    {
        public string Encode(StateData data)=>JsonUtility.ToJson(data);
        public StateData Decode(string json)=>Decode(json,0);
        static string[] MigrationFields(int version){if(version<16||version>19)return null;var fields=new System.Collections.Generic.List<string>();void Add(string type,params string[] names){foreach(string name in names)fields.Add("IdleIntelligence.Core."+type+"."+name);}Add("LegacyState","classUpgrades","classUpgradesRecorded");if(version==19)return fields.ToArray();Add("MainStateData","guidance","runCredits","runCreditsRecorded","lifetimeCreditsExact","lifetimeCreditsExactRecorded","lifetimeEligibleExact","lifetimeEligibleExactRecorded","lifetimeDataExact","lifetimeDataExactRecorded");Add("LocalJournal","diagnostics");Add("LocalBalanceHistory","measurementKnown");Add("BalanceObservation","lifetimeCredits","lifetimeEligible","lifetimeData","lifetimeCreditsRecorded","lifetimeEligibleRecorded","lifetimeDataRecorded","metaBalancesRecorded","projectLevelsRecorded","modelLevelsRecorded","fullRecorded","runCreditsRecorded","gems","paidIncome","adFree","nodeIds","equipped","research","modelLevels","inventory","totalINT","unspentINT","spentINT","availableAxioms","totalAxioms","knowledge");if(version==18)return fields.ToArray();if(version==16)Add("MainStateData","story","storyRecorded","journal","returnReceipt");Add("MainStateData","webArchive","legacy");Add("LocalJournal","history","returns","challengeEvents","droppedChallengeEvents","measuredTaps","tapsRecorded");Add("WorkshopState","blueprintPending");Add("Job","startedAt","startRecorded");Add("AnalysisJob","startedAt","startRecorded");Add("LocalEvent","costsRecorded","durationRecorded","actualSeconds","creditCost","dataCost");Add("BalanceRunRecord","events","droppedEventKinds");Add("BalanceObservation","hardwareRecorded","labsRecorded");Add("ReturnReceipt","components","items","fragments","researchFragments");return fields.ToArray();}
        public StateData Decode(string json,int version){SaveJsonValidation.Validate(json,typeof(StateData),version>=16,MigrationFields(version));var decoded=JsonUtility.FromJson<StateData>(json);if(version>0&&version<20){RestoreClassUpgrades(decoded,!decoded.hasChallenge,decoded.challengeRun?.runId);if(decoded.hasChallenge)RestoreClassUpgrades(decoded.challengeMain,true,null);}return decoded;}
        static void RestoreClassUpgrades(MainStateData data,bool mainContext,string runId){if(data.legacy==null||data.legacy.classUpgradesRecorded)return;data.legacy.classUpgrades=System.Array.Empty<string>();if(data.webArchive?.present==true){var root=SaveJsonValidation.Parse(data.webArchive.normalized).Field("state");var session=root.Field("challengeSession");bool archivedChallenge=session!=null&&session.Kind!="null";if(mainContext&&archivedChallenge)root=session.Field("main");else if(!mainContext&&(!archivedChallenge||root.Field("retention")?.Field("activeRun")?.Field("runId")?.Text!=runId))root=null;if(root!=null&&root.Field("prestigeCount")?.Text==data.prestige.resets.ToString(System.Globalization.CultureInfo.InvariantCulture)&&root.Field("axiomResetCount")?.Text==data.meta.resets.ToString(System.Globalization.CultureInfo.InvariantCulture)){var upgrades=root.Field("classUpgrades");if(upgrades?.Kind=="array")data.legacy.classUpgrades=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Select(upgrades.Items,x=>x.Text));}}data.legacy.classUpgradesRecorded=true;}
        public string EncodeEnvelope(SaveEnvelope data)=>JsonUtility.ToJson(data);
        public SaveEnvelope DecodeEnvelope(string json){SaveJsonValidation.Validate(json,typeof(SaveEnvelope),true);return JsonUtility.FromJson<SaveEnvelope>(json);}
    }
}
